from solution import fibfib

import pytest
from hypothesis import given
import hypothesis.strategies as st


def reference_fibfib(n: int) -> int:
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1
    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c


# --- concrete examples from spec docstring ---

def test_example_fibfib_1_is_0():
    assert fibfib(1) == 0


def test_example_fibfib_5_is_4():
    assert fibfib(5) == 4


def test_example_fibfib_8_is_24():
    assert fibfib(8) == 24


# --- base cases from spec ---

def test_base_cases_match_spec():
    assert fibfib(0) == 0
    assert fibfib(1) == 0
    assert fibfib(2) == 1


def test_first_values_derived_from_recurrence():
    # 0,0,1,1,2,4,7,13,24,44 derived by repeated spec recurrence
    expected = [0, 0, 1, 1, 2, 4, 7, 13, 24, 44]
    for n, v in enumerate(expected):
        assert fibfib(n) == v


# --- properties ---

@given(st.integers(min_value=0, max_value=30))
def test_equivalence_to_reference_model(n):
    assert fibfib(n) == reference_fibfib(n)


@given(st.integers(min_value=3, max_value=30))
def test_recurrence_relation_holds(n):
    assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)


@given(st.integers(min_value=0, max_value=30))
def test_result_is_nonnegative_int(n):
    v = fibfib(n)
    assert isinstance(v, int)
    assert not isinstance(v, bool)
    assert v >= 0


@given(st.integers(min_value=2, max_value=30))
def test_monotone_nondecreasing_from_n2(n):
    assert fibfib(n + 1) >= fibfib(n)


@given(st.integers(min_value=4, max_value=30))
def test_strictly_increasing_from_n3(n):
    # for n>=3 values are strictly increasing: difference is sum of two earlier nonneg terms, positive
    assert fibfib(n + 1) > fibfib(n)


@given(st.integers(min_value=0, max_value=25))
def test_shift_invariance_of_recurrence(n):
    # fibfib(n+3) computed from triple equals reference triple shift
    assert fibfib(n + 3) - fibfib(n + 2) - fibfib(n + 1) == fibfib(n)


def test_efficient_large_n_matches_reference():
    # "efficiently compute": must handle moderately large n quickly and exactly
    for n in (50, 100, 200, 300):
        assert fibfib(n) == reference_fibfib(n)


def test_efficient_large_n_positive_and_growing():
    a = fibfib(100)
    b = fibfib(101)
    assert isinstance(a, int) and a > 0
    assert b > a
    # tribonacci growth: b < 2*a for large n (since ratio -> ~1.839)
    assert b < 2 * a
